14:36:41.411 [Test worker] INFO  com.rsmaxwell.diaries.responder.sync.Synchronise -          value: {"id":2075,"version":0,"year":1834,"month":5,"day":27,"sequence":1.0000,"text":"<p>Fine weather &amp; blowing fresh from the NE &amp; sea high. H Hurry dined with me. At the Pig &amp; Whistle. Took tea with C Cockrill. Walked to Tynemouth in the evening &amp; fresh. At the Albion.</p>","pageId":1080,"type":"MARQUEE","imageId":null,"marqueeId":2015,"lock":null}
14:36:41.411 [Test worker] INFO  com.rsmaxwell.diaries.responder.sync.Synchronise - Difference detected on topic: diaries/fragments/2076
14:36:41.411 [Test worker] INFO  com.rsmaxwell.diaries.responder.sync.Synchronise -           DB:   {"id":2076,"version":0,"year":1834,"month":5,"day":28,"sequence":1.0000,"text":"<p>Fine weather. Wind NE. The Kings birthday. Took a walk with C Cockrill to Tynemouth. The military fired a salute. Went round by Cullercoats where I bought an old net for C Richardson for 10/- Whitley &amp; Preston home &amp; dined with C Cockrill. Met Bess</p>","pageId":1080,"type":"MARQUEE","imageId":null,"marqueeId":2016,"lock":null}
14:36:41.411 [Test worker] INFO  com.rsmaxwell.diaries.responder.sync.Synchronise -           Tree: null
