14:36:41.694 [Test worker] INFO  com.rsmaxwell.diaries.responder.sync.Synchronise -           DB:   {"id":578,"version":0,"year":1829,"month":6,"day":27,"sequence":1.0000,"text":"<figure>\r\n  <img src=\"images/img2893-image-kopu-lighthouse.jpg\" width=\"600px\" />\r\n  <figcaption>Kopu Lighthouse</figcaption>\r\n</figure>","pageId":null,"type":null,"imageId":null,"marqueeId":null,"lock":null}
