14:36:41.770 [Test worker] INFO  com.rsmaxwell.diaries.responder.sync.Synchronise -           DB:   {"id":733,"version":0,"year":1829,"month":10,"day":20,"sequence":1.0000,"text":"<p>A dull morning &amp; showery. Wind S by W. Out with my gun. <span class=highlight_yellow>But</span> did not get a shot. Kit &amp; Joe out hunting. They had good sport. Spent the evening at home.</p>","pageId":779,"type":"MARQUEE","imageId":null,"marqueeId":688,"lock":null}
